import{_ as o,o as t,c as a,a5 as c}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"Task — G1 Authentication (Mobile)","description":"","frontmatter":{},"headers":[],"relativePath":"mobile/features/g1-auth/task.md","filePath":"mobile/features/g1-auth/task.md"}'),i={name:"mobile/features/g1-auth/task.md"};function r(d,e,l,s,n,u){return t(),a("div",null,[...e[0]||(e[0]=[c('<h1 id="task-—-g1-authentication-mobile" tabindex="-1">Task — G1 Authentication (Mobile) <a class="header-anchor" href="#task-—-g1-authentication-mobile" aria-label="Permalink to &quot;Task — G1 Authentication (Mobile)&quot;">​</a></h1><p>&gt; <a href="./spec.html">spec.md</a> | <a href="./plan.html">plan.md</a> | <a href="./test.html">test.md</a></p><h2 id="infra-chung" tabindex="-1">Infra chung <a class="header-anchor" href="#infra-chung" aria-label="Permalink to &quot;Infra chung&quot;">​</a></h2><ul><li>[ ] Axios instance + response interceptor auto-refresh 401 (<code>POST /auth/refresh</code>, retry request gốc).</li><li>[ ] <code>expo-secure-store</code> wrapper: <code>getTokens()</code>, <code>setTokens()</code>, <code>clearTokens()</code>.</li><li>[ ] <code>useAuthStore</code> (Zustand) — <code>accessToken</code>, <code>refreshToken</code>, <code>user</code>, <code>lastUsedPlatform</code>, <code>isAuthenticated</code>, <code>setAuth()</code>, <code>setTokens()</code>, <code>clearAuth()</code>.</li><li>[ ] Bảng message lỗi tiếng Việt tập trung (map <code>ErrorCode</code> → string).</li><li>[ ] Deep link scheme <code>brandhub</code> đăng ký trong <code>app.json</code>/<code>app.config.ts</code>.</li></ul><h2 id="login-register-otp" tabindex="-1">Login / Register / OTP <a class="header-anchor" href="#login-register-otp" aria-label="Permalink to &quot;Login / Register / OTP&quot;">​</a></h2><ul><li>[ ] <code>useLoginMutation</code> — <code>POST /auth/login</code>, set Zustand store khi không cần 2FA, điều hướng <code>TwoFactorVerify</code> khi <code>requireTwoFactor === true</code>.</li><li>[ ] <code>useRegisterMutation</code> — <code>POST /auth/register</code>, điều hướng <code>VerifyOtp(email, purpose=register)</code> sau khi có <code>userId</code>.</li><li>[ ] <code>useVerifyOtpMutation</code>, <code>useResendOtpMutation</code> (cooldown 60s client-side).</li><li>[ ] Screen <code>Login</code>: form identifier+password, link &quot;Quên mật khẩu?&quot;, nút Google OAuth, link Register, highlight nút Google nếu <code>lastUsedPlatform === &quot;google&quot;</code>.</li><li>[ ] Screen <code>Register</code>: form email+password+fullName, hiển thị rule password (&gt;=8 ký tự + có số).</li><li>[ ] Screen <code>VerifyOtp</code>: 6 ô nhập OTP, nút &quot;Gửi lại mã&quot; với cooldown.</li></ul><h2 id="forgot-reset-password" tabindex="-1">Forgot / Reset Password <a class="header-anchor" href="#forgot-reset-password" aria-label="Permalink to &quot;Forgot / Reset Password&quot;">​</a></h2><ul><li>[ ] <code>useForgotPasswordMutation</code> — <code>POST /auth/forgot-password</code>, luôn hiển thị message thành công chung.</li><li>[ ] <code>useResetPasswordMutation</code> — <code>POST /auth/reset-password</code> với <code>{ token, newPassword }</code>.</li><li>[ ] Screen <code>ForgotPassword</code>: 1 input email.</li><li>[ ] Screen <code>ResetPassword</code>: đọc <code>token</code> từ deep link query param, input <code>newPassword</code> + <code>confirmPassword</code> (client-side validate).</li><li>[ ] Deep link handler: <code>brandhub://reset-password?token=...</code> → mở thẳng <code>ResetPassword</code> screen.</li></ul><h2 id="google-oauth" tabindex="-1">Google OAuth <a class="header-anchor" href="#google-oauth" aria-label="Permalink to &quot;Google OAuth&quot;">​</a></h2><ul><li>[ ] <code>startUrl</code> = <code>{API_BASE_URL}/api/v1/auth/oauth/google?client=mobile</code> (param <code>client=mobile</code> bắt buộc).</li><li>[ ] <code>returnUrl</code> = <code>makeRedirectUri({ scheme: &quot;brandhub&quot;, path: &quot;oauth-callback&quot; })</code>.</li><li>[ ] <code>WebBrowser.openAuthSessionAsync(startUrl, returnUrl)</code> → parse <code>result.url</code> lấy <code>token</code>/<code>error</code>.</li><li>[ ] Sau khi có token: lưu SecureStore → gọi <code>GET /api/v1/users/me</code> lấy profile đầy đủ → set Zustand store.</li><li>[ ] Xử lý <code>error=ACCOUNT_SUSPENDED</code> riêng (toast khác), còn lại → toast chung &quot;Đăng nhập Google thất bại&quot;.</li><li>[ ] Set <code>lastUsedPlatform = &quot;google&quot;</code> khi thành công.</li></ul><h2 id="_2fa-verify" tabindex="-1">2FA Verify <a class="header-anchor" href="#_2fa-verify" aria-label="Permalink to &quot;2FA Verify&quot;">​</a></h2><ul><li>[ ] <code>useVerifyTwoFactorMutation</code> — <code>POST /auth/2fa/verify</code> với <code>{ twoFactorToken, code }</code>.</li><li>[ ] Screen <code>TwoFactorVerify</code>: nhận <code>twoFactorToken</code> qua navigation param, input 6 số, giữ token hiệu lực khi nhập sai (không tự quay về Login).</li></ul><h2 id="logout" tabindex="-1">Logout <a class="header-anchor" href="#logout" aria-label="Permalink to &quot;Logout&quot;">​</a></h2><ul><li>[ ] <code>useLogoutMutation</code> — <code>POST /auth/logout</code> với body <code>{ refreshToken }</code> (<strong>bắt buộc gửi</strong>, backend đã hỗ trợ đọc từ body).</li><li>[ ] Luôn <code>clearAuth()</code> ở <code>onSettled</code> dù API lỗi.</li><li>[ ] <code>lastUsedPlatform</code> KHÔNG bị xoá trong <code>clearAuth()</code> — chỉ xoá token/user.</li></ul><h2 id="error-loading-states-chung" tabindex="-1">Error/Loading states chung <a class="header-anchor" href="#error-loading-states-chung" aria-label="Permalink to &quot;Error/Loading states chung&quot;">​</a></h2><ul><li>[ ] Mọi submit button: disable + spinner khi đang gọi API.</li><li>[ ] Lỗi network (timeout, no response): toast riêng &quot;Không thể kết nối, vui lòng thử lại&quot;.</li><li>[ ] <code>tsc --noEmit</code> pass, không lỗi type.</li></ul><h2 id="chua-lam-out-of-scope-g1-xem-spec-muc-7" tabindex="-1">Chưa làm / out of scope G1 (xem spec mục 7) <a class="header-anchor" href="#chua-lam-out-of-scope-g1-xem-spec-muc-7" aria-label="Permalink to &quot;Chưa làm / out of scope G1 (xem spec mục 7)&quot;">​</a></h2><ul><li>[ ] Không làm: Setup 2FA (QR), Disable 2FA, Change Password, Deactivate Account, Link/Unlink Phone/OAuth, Profile đầy đủ (View/Update).</li></ul>',18)])])}const p=o(i,[["render",r]]);export{g as __pageData,p as default};
